import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';
import './index.css';

import React from 'react';
import ReactDOM from 'react-dom/client';
import {Provider} from '@gravity-ui/uikit';

import {App} from './App';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <Provider theme="system" lang="ru">
      <App />
    </Provider>
  </React.StrictMode>,
);
EOF
cat > src/index.css <<'EOF'
body {
  margin: 0;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: var(--g-spacing-4);
  box-sizing: border-box;
  background: var(--g-color-base-background);
}

.login-card {
  width: 100%;
  max-width: 400px;
}
EOF
cat > src/App.tsx <<'EOF'
import React from 'react';
import {Button, Card, Checkbox, Flex, PasswordInput, Text, TextInput} from '@gravity-ui/uikit';

export function App() {
  const [email, setEmail] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [rememberMe, setRememberMe] = React.useState(false);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    // TODO: подключить реальную авторизацию
    console.info('login', {email, rememberMe});
  };

  return (
    <main className="page">
      <Card className="login-card" type="container" view="outlined" spacing={{p: 6}}>
        <form onSubmit={handleSubmit}>
          <Flex direction="column" gap={5}>
            <Text variant="header-1">Вход</Text>

            <Flex direction="column" gap={4}>
              <TextInput
                type="email"
                name="email"
                size="l"
                label="Email"
                placeholder="name@example.com"
                autoComplete="email"
                value={email}
                onUpdate={setEmail}
                controlProps={{required: true}}
              />
              <PasswordInput
                name="password"
                size="l"
                label="Пароль"
                autoComplete="current-password"
                value={password}
                onUpdate={setPassword}
                controlProps={{required: true}}
              />
              <Checkbox size="l" checked={rememberMe} onUpdate={setRememberMe}>
                Запомнить меня
              </Checkbox>
            </Flex>

            <Button type="submit" view="action" size="xl" width="max">
              Войти
            </Button>
          </Flex>
        </form>
      </Card>
    </main>
  );
}
EOF
npm run build 2>&1 | tail -30

